CREATE TABLE public.umsatz (
  id         bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  monat      date          NOT NULL,
  bezirk     text          NOT NULL,
  betrag     numeric(12,2) NOT NULL,
  erfasst_am timestamptz   NOT NULL DEFAULT now()
);

ALTER TABLE public.umsatz ENABLE ROW LEVEL SECURITY;

CREATE INDEX umsatz_monat_idx ON public.umsatz (monat);
